// Photo-real sprite layers as data URIs (text-safe for GitHub Pages).
window.ROACH_EMBED = {
  'roach-body.webp': 'data:image/webp;base64,',
  'roach-antL.webp': 'data:image/webp;base64,',
  'roach-antR.webp': 'data:image/webp;base64,',
  'roach-lL1.webp': 'data:image/webp;base64,',
  'roach-lL2.webp': 'data:image/webp;base64,',
  'roach-lL3.webp': 'data:image/webp;base64,',
  'roach-lR1.webp': 'data:image/webp;base64,',
  'roach-lR2.webp': 'data:image/webp;base64,',
  'roach-lR3.webp': 'data:image/webp;base64,',
};

(function () {
  var map = window.ROACH_EMBED;
  if (!map) return;
  document.querySelectorAll('#pet img').forEach(function (img) {
    var name = (img.getAttribute('src') || '').split('/').pop();
    if (map[name]) img.src = map[name];
  });
})();
